SELECT * FROM announcements WHERE status = 1 AND (publish_at IS NULL OR publish_at <= NOW())
AND type = #{type}
ORDER BY is_pinned DESC, priority DESC, publish_at DESC, created_at DESC

SELECT * FROM announcements WHERE 1=1

    AND title LIKE CONCAT('%', #{keyword}, '%')


    AND type = #{type}


    AND status = #{status}

ORDER BY is_pinned DESC, priority DESC, created_at DESC

SELECT COUNT(*) FROM announcements WHERE 1=1

    AND title LIKE CONCAT('%', #{keyword}, '%')


    AND type = #{type}


    AND status = #{status}
